def _select_mode(sampler: CoordinateSampler, adjustment_epoch: int) -> int:
    weights = MODE_WEIGHTS[adjustment_epoch % 3]
    draw = sampler.u("mode", 0, 0, sum(weights) - 1)
    if draw < weights[0]:
        return 0
    if draw < weights[0] + weights[1]:
        return 1
    return 2


